// Generated by scripts/gen_themes.py with the CSS in app.css (contrast-checked palettes).

export interface ThemeInfo {
  key: string;
  name: string;
  zh: string;
  /** A character shown on the swatch, or "flower" for drawn blossoms. */
  emblem: string;
  dark: boolean;
  bg: string;
  surface: string;
  accent: string;
  accentSoft: string;
  /** Which row of the picker it sits in. */
  group: ThemeGroup;
}

/** The picker's rows, in order. */
export const THEME_GROUPS = ["soft", "bold", "calm"] as const;
export type ThemeGroup = (typeof THEME_GROUPS)[number];

